def reverseDegree(s: str) -> int:
    reverse_alphabet = {chr(i): 26 - (i - 97) for i in range(97, 123)}
    total = 0
    for index, char in enumerate(s):
        position_in_reversed_alphabet = reverse_alphabet[char]
        total += position_in_reversed_alphabet * (index + 1)
    return total

