def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    # dp[i] will store the length of the longest subsequence ending with nums[i]
    dp = [1] * n

    # Iterate through the array to fill dp array
    for i in range(n):
        for j in range(i):
            # Calculate the absolute difference
            diff1 = abs(nums[i] - nums[j])
            # We need to check if the sequence continues non-increasingly
            valid = True
            for k in range(j):
                if abs(nums[k] - nums[k + 1]) < diff1:
                    valid = False
                    break
            if valid:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def calculateScore(s: str) -> int:
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}
    marked = [False] * len(s)
    score = 0
    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror[s[i]]:
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

