def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Initialize with the value at (0, 0)

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k counts the neutralizations used
                if i > 0:
                    new_coins = dp[i-1][j][k] + coins[i][j]
                    if coins[i][j] < 0 and k < 2:
                        # Neutralizing this robber
                        dp[i][j][k + 1] = max(dp[i][j][k + 1], new_coins + 2 * coins[i][j])
                    # Record unneutralized state
                    dp[i][j][k] = max(dp[i][j][k], new_coins)
                if j > 0:
                    new_coins = dp[i][j-1][k] + coins[i][j]
                    if coins[i][j] < 0 and k < 2:
                        # Neutralizing this robber
                        dp[i][j][k + 1] = max(dp[i][j][k + 1], new_coins + 2 * coins[i][j])
                    # Record unneutralized state
                    dp[i][j][k] = max(dp[i][j][k], new_coins)

    return max(dp[m-1][n-1][k] for k in range(3))

