import collections


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    def canReachNode0(maxWeight):
        graph = collections.defaultdict(list)
        # Build graph with weights <= maxWeight
        for u, v, w in edges:
            if w <= maxWeight:
                graph[v].append(u)

        # BFS to check if all nodes can reach node 0
        reachable = set()
        queue = collections.deque([0])
        while queue:
            node = queue.popleft()
            if node not in reachable:
                reachable.add(node)
                for neighbor in graph[node]:
                    if neighbor not in reachable:
                        queue.append(neighbor)

        return len(reachable) == n

    left, right = 1, max(w for _, _, w in edges)
    answer = -1

    while left <= right:
        mid = (left + right) // 2
        if canReachNode0(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    return answer

