MOD = 10**9 + 7


def minMaxSums(nums: List[int], k: int) -> int:
    n = len(nums)
    total_sum = 0
    for i in range(1, k + 1):
        for num in nums:
            num_contribution = num * comb(n - 1, i - 1) % MOD
            total_sum += num_contribution * (pow(2, n - i, MOD)) % MOD
            total_sum %= MOD
    total_sum = (total_sum * 2) % MOD  # Each number contributes as both min and max
    return total_sum


def comb(n: int, k: int) -> int:
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)  # Take advantage of symmetry
    c = 1
    for i in range(k):
        c = c * (n - i) % MOD
        c = c * pow(i + 1, MOD - 2, MOD) % MOD  # Modular inverse
    return c

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    event_queue = []

    # Process events and handle the online/offline status
    for event in events:
        event_type, timestamp, *data = event
        timestamp = int(timestamp)

        if event_type == 'OFFLINE':
            user_id = int(data[0])
            online_status[user_id] = False
            event_queue.append((timestamp + 60, user_id, 'ONLINE'))

        elif event_type == 'MESSAGE':
            # First, process any user going online
            while event_queue and event_queue[0][0] <= timestamp:
                _, user_id, status = event_queue.pop(0)
                online_status[user_id] = (status == 'ONLINE')

            mentions_string = data[0]
            if mentions_string == 'ALL':
                for i in range(numberOfUsers):
                    mentions[i] += 1  # Count for all users
            elif mentions_string == 'HERE':
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1  # Count only online users
            else:
                for mention in mentions_string.split():
                    user_id = int(mention[2:])
                    mentions[user_id] += 1  # Count individual mentions

    return mentions
